contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(putAmount > 0, "putAmount must be positive");
        require(address(this).balance >= putAmount, "not enough balance");

        uint beforeBalance = uint(0);
        {
            (bool _ok, bytes memory _ret) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", address(this)));
            require(_ok, "Acc getter failed");
            (beforeBalance) = abi.decode(_ret, (uint));
        }

        uint beforeMinSum = c.MinSum();

        c.Put{value: putAmount}(lockTime);

        uint afterBalance = uint(0);
        {
            (bool _ok2, bytes memory _ret2) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", address(this)));
            require(_ok2, "Acc getter failed");
            (afterBalance) = abi.decode(_ret2, (uint));
        }

        uint afterMinSum = c.MinSum();

        bool putGrewBalance = (afterBalance == beforeBalance + putAmount);
        bool minSumUnchangedByPut = (afterMinSum == beforeMinSum);

        uint beforeCollectBalance = afterBalance;

        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint afterCollectBalance = uint(0);
        {
            (bool _ok3, bytes memory _ret3) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", address(this)));
            require(_ok3, "Acc getter failed");
            (afterCollectBalance) = abi.decode(_ret3, (uint));
        }

        bool collectBalanced = collectReverted || (afterCollectBalance == beforeCollectBalance - collectAmount);

        assert(putGrewBalance && minSumUnchangedByPut && collectBalanced);
    }

    receive() external payable {}
}

